     *  Switch: '<S34>/Switch1' *)
    FL_sCalculated_Vtg_Diff_BB3 := FL_sVtgExt_BB3;
ELSE 
    (* Switch: '<S34>/Switch2' incorporates:
     *  MinMax: '<S34>/Min'
     *  Product: '<S34>/Product3'
     *  Product: '<S34>/Product4'
     *  Product: '<S34>/Product5'
