FL_sCalculated_Vtg_Diff_BB1 := ABS(VtgInt_BB1 - FL_sCalculated_Vtg_Diff_BB3);
(* Abs: '<S34>/Abs1' incorporates:
 *  Sum: '<S34>/Subtract1' *)
FL_sCalculated_Vtg_Diff_BB2 := ABS(VtgInt_BB2 - FL_sCalculated_Vtg_Diff_BB3);
(* Sum: '<S34>/Subtract2' *)
FL_sCalculated_Vtg_Diff_BB3 := VtgInt_BB3 - FL_sCalculated_Vtg_Diff_BB3;
(* Abs: '<S34>/Abs2' *)
