FL_boSafeToCloseHV_BB3 := (FL_sCalculated_Vtg_Diff_BB3 < SafeVoltageToCloseHV_V) OR ((FL_sCalculated_InrushCurrent_BB3 < SafeCurrentToCloseHV_A) AND FL_boSafeToCloseHV_BB3);

(* Logic: '<S703>/AND7' incorporates: * Logic: '<S703>/NOT' *) rtb_AND7 := ( NOT IP_boBMS_SDError_BB1) AND (IP_boBMS_Batt1_Availability <> 0.0); (* Switch: '<S703>/Switch4' incorporates: * Constant: '<S703>/Constant6' *)
IF rtb_AND7 THEN rtb_Switch4_o := REAL_TO_LREAL(IP_sBMS_VtgInt_BB1); ELSE rtb_Switch4_o := 0.0; END_IF;
