(* Logic: '<S703>/AND8' incorporates: * Logic: '<S703>/NOT1' *) rtb_AND8 := ( NOT IP_boBMS_SDError_BB2) AND (IP_boBMS_Batt2_Availability <> 0.0); (* Switch: '<S703>/Switch5' incorporates: * Constant: '<S703>/Constant7' *)
