(* End of Switch: '<S703>/Switch5' *)
(* Logic: '<S703>/AND9' incorporates: * Logic: '<S703>/NOT2' *) rtb_AND9 := ( NOT IP_boBMS_SDError_BB3) AND (IP_boBMS_Batt3_Availability <> 0.0); (* Switch: '<S703>/Switch6' incorporates: * Constant: '<S703>/Constant8' *)
IF rtb_AND9 THEN rtb_Switch6 := REAL_TO_LREAL(IP_sBMS_VtgInt_BB3); ELSE rtb_Switch6 := 0.0; END_IF;
(* End of Switch: '<S703>/Switch6' *)
(* Switch: '<S703>/Switch7' incorporates: * Constant: '<S703>/Constant9' * Constant: '<S707>/Constant' * Logic: '<S703>/AND4' * RelationalOperator: '<S707>/Compare' *)
IF (IP_sBMS_VtgInt_BB1 > 10.0) AND rtb_AND7 THEN rtb_Switch7 := IP_sBMS_VtgInt_BB1; ELSE rtb_Switch7 := UINT_TO_REAL(Voltage_NA_UB); END_IF;
(* End of Switch: '<S703>/Switch7' *)
(* Switch: '<S703>/Switch8' incorporates: * Constant: '<S703>/Constant9' * Constant: '<S708>/Constant' * Logic: '<S703>/AND5' * RelationalOperator: '<S708>/Compare' *)
IF (IP_sBMS_VtgInt_BB2 > 10.0) AND rtb_AND8 THEN rtb_Switch8 := IP_sBMS_VtgInt_BB2; ELSE rtb_Switch8 := UINT_TO_REAL(Voltage_NA_UB); END_IF;
(* End of Switch: '<S703>/Switch8' *)
(* Switch: '<S703>/Switch9' incorporates: * Constant: '<S703>/Constant9' * Constant: '<S709>/Constant' * Logic: '<S703>/AND6' * RelationalOperator: '<S709>/Compare' *)
IF (IP_sBMS_VtgInt_BB3 > 10.0) AND rtb_AND9 THEN rtb_Switch9 := IP_sBMS_VtgInt_BB3; ELSE rtb_Switch9 := UINT_TO_REAL(Voltage_NA_UB); END_IF;
(* End of Switch: '<S703>/Switch9' *)
(* Switch: '<S703>/Switch' incorporates: * Constant: '<S703>/Constant' * Logic: '<S703>/AND' * Logic: '<S703>/AND1' * RelationalOperator: '<S703>/GreaterThan' * RelationalOperator: '<S703>/GreaterThan1' * RelationalOperator: '<S703>/GreaterThan2' * RelationalOperator: '<S703>/GreaterThan3' * Switch: '<S703>/Switch1' *)
IF (rtb_Switch4_o >= rtb_Switch5_d) AND (rtb_Switch4_o >= rtb_Switch6) THEN IT_u8BMS_BB_No_MaxVoltage := BattBox1_No; ELSIF (rtb_Switch5_d >= rtb_Switch4_o) AND (rtb_Switch5_d >= rtb_Switch6) THEN (* Switch: '<S703>/Switch1' incorporates: * Constant: '<S703>/Constant1' *) IT_u8BMS_BB_No_MaxVoltage := BattBox2_No; ELSE (* Switch: '<S703>/Switch1' incorporates: * Constant: '<S703>/Constant2' *) IT_u8BMS_BB_No_MaxVoltage := BattBox3_No; END_IF;
(* End of Switch: '<S703>/Switch' *)
(* Switch: '<S703>/Switch2' incorporates: * Constant: '<S703>/Constant' * Logic: '<S703>/AND2' * Logic: '<S703>/AND3' * RelationalOperator: '<S703>/GreaterThan4' * RelationalOperator: '<S703>/GreaterThan5' * RelationalOperator: '<S703>/GreaterThan6' * RelationalOperator: '<S703>/GreaterThan7' * Switch: '<S703>/Switch3' *)
IF (rtb_Switch7 <= rtb_Switch8) AND (rtb_Switch7 <= rtb_Switch9) THEN IT_u8BMS_BB_No_MinVoltage := BattBox1_No; ELSIF (rtb_Switch8 <= rtb_Switch7) AND (rtb_Switch8 <= rtb_Switch9) THEN (* Switch: '<S703>/Switch3' incorporates: * Constant: '<S703>/Constant1' *) IT_u8BMS_BB_No_MinVoltage := BattBox2_No; ELSE (* Switch: '<S703>/Switch3' incorporates: * Constant: '<S703>/Constant2' *) IT_u8BMS_BB_No_MinVoltage := BattBox3_No; END_IF;
(* End of Switch: '<S703>/Switch2' *)

IF in THEN 
    PLC_BOOL_TO_LREAL := 1.0;
ELSE 
    PLC_BOOL_TO_LREAL := 0.0;
END_IF;

CASE timerAction OF
    1:
        (* RESET *)
        plcTimer(IN:=FALSE, PT:=T#0ms);
        plcTimerExpired := FALSE;
        done := FALSE;
    2:
        (* AFTER *)
        IF (NOT(plcTimerExpired)) THEN
            plcTimer(IN:=TRUE, PT:=DINT_TO_TIME(maxTime));
        END_IF;
        plcTimerExpired := plcTimer.Q;
        done := plcTimerExpired;
    3:
        (* BEFORE *)
        IF (NOT(plcTimerExpired)) THEN
            plcTimer(IN:=TRUE, PT:=DINT_TO_TIME(maxTime));
        END_IF;
        plcTimerExpired := plcTimer.Q;
        done := NOT(plcTimerExpired);
END_CASE;
